import traceback
def read_age(text):
    return int(text)
def load(record):
    return read_age(record['age'])
try:
    load({'age': 'abc'})
except ValueError as e:
    print('caught:', e)
    frames = traceback.extract_tb(e.__traceback__)
    print([f.name for f in frames])

