def average(scores):
    if len(scores) == 0:
        raise ValueError('give at least one score')
    total = sum(scores)
    assert total >= 0, f'negative total: {total}'
    return total / len(scores)
for data in ([4, 6], [], [-5, 1]):
    try:
        print(average(data))
    except (ValueError, AssertionError) as e:
        print(type(e).__name__ + ':', e)

import sys
def add(a, b):
    total = a + b
    return total
def main():
    x = add(2, 3)
    return add(x, 10)
steps = []
def watch(f, event, arg):
    if event == 'line':
        steps.append((f.f_code.co_name, dict(f.f_locals)))
    return watch
sys.settrace(watch)
main()
sys.settrace(None)
print(*steps, sep='\n')
